head.script:
scwin.onpageload = function() {
    // IFrame 팝업으로 tabControlMain.xml을 오픈한 경우 onpageload 함수가 호출되지 않고
    // Tab1에서 wframePreload로 Include한 wframe1.xml의 onpageload 함수가 2번 호출됨
    var frameId = $p.getFrameId() || $p.getParameter("w2xPath");
    console.log("onpageload - " + frameId + " Frame");
};
scwin.onpageunload = function() {};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
